import{C as e,H as t,L as n,N as r,S as i,g as a,n as o,w as s,x as c,y as l}from"./useSeo-iBvXYvyG.js";import{o as u}from"./share-44xUZnx-.js";var d={class:`mx-auto max-w-[46rem] px-4 py-12`},f={class:`mt-12 flex flex-wrap gap-4 border-t-2 border-tambouille-rule pt-8`},p=s({__name:`AboutView`,setup(s){return o({title:`Comment ça marche`,description:`Tambouille est un site d’écoute et de partage de mix. Déposer un mix, importer depuis Mixcloud ou un flux podcast, suivre des comptes, s’abonner en RSS : ce que le site fait, et comment.`,canonical:u({name:`about`})}),(o,s)=>{let u=n(`RouterLink`);return r(),l(`div`,d,[s[2]||=c(`<p class="tb-eyebrow">Comment ça marche</p><h1 class="text-tambouille-title-big leading-none">Tambouille</h1><p class="mt-8 text-[19px] leading-relaxed"> Un endroit pour déposer des mix, les écouter, et retrouver ceux des autres. Pas de recommandation automatique, pas de fil sans fin : ce qui remonte ici a été déposé ou choisi par quelqu&#39;un. </p><h2 class="mt-12 font-display text-2xl font-bold">Écouter</h2><p class="mt-3 leading-relaxed"> La lecture ne s&#39;arrête pas quand tu changes de page : le lecteur reste en bas de l&#39;écran et continue pendant que tu navigues. La forme d&#39;onde permet de se déplacer dans le mix d&#39;un clic. </p><p class="mt-3 leading-relaxed"> Quand un mix a une tracklist, chaque morceau porte son minutage : cliquer dessus saute directement au passage. Les commentaires fonctionnent pareil — chacun s&#39;accroche à un moment du mix plutôt qu&#39;au mix entier, et y renvoie. Seules les réponses à un commentaire n&#39;ont pas de minutage. </p><h2 class="mt-12 font-display text-2xl font-bold">Déposer un mix</h2><p class="mt-3 leading-relaxed"> Deux façons. Envoyer un fichier audio depuis ton disque, avec une pochette, un titre, une description et des tags. Ou coller un lien : le site va lire la page, en rapporte le titre, la description, la pochette, les tags et la tracklist quand la source les donne, et remplit le formulaire pour toi. Tout reste modifiable avant publication. </p><p class="mt-3 leading-relaxed">Les sources reconnues :</p><ul class="mt-2 list-disc space-y-1 pl-5 leading-relaxed"><li>Mixcloud et SoundCloud</li><li>Archive.org</li><li>Ouïedire, LYL Radio, The Brain</li><li>n&#39;importe quel flux RSS de podcast</li></ul><p class="mt-3 leading-relaxed"> Sur un import, tu choisis où vit l&#39;audio : copié chez nous, ou laissé chez la source, qui continue alors de le servir. Dans les deux cas le mix a sa page ici. </p><p class="mt-3 leading-relaxed"> Si la source a déjà été importée, le site te le dit et refuse la publication, avec un lien vers le mix existant. C&#39;est ce qui évite les doublons. </p><h2 class="mt-12 font-display text-2xl font-bold">Les fournées</h2><p class="mt-3 leading-relaxed"> Une fournée est une sélection de quelques mix, numérotée, présentée par la personne qui l&#39;a composée. Elle occupe le haut de l&#39;accueil pendant sa saison, puis laisse la place à la suivante. C&#39;est la seule chose du site qui soit choisie à la main plutôt que classée par une date ou un compteur. </p><h2 class="mt-12 font-display text-2xl font-bold">Retrouver</h2><p class="mt-3 leading-relaxed"> La recherche cherche dans les titres, les descriptions et les artistes, ainsi que parmi les comptes — au clavier, <kbd class="tb-tag">⌘K</kbd> y pose le curseur. Les tags filtrent la liste, et se cumulent. </p><p class="mt-3 leading-relaxed"> Un cœur met un mix de côté, une playlist en regroupe plusieurs dans l&#39;ordre que tu veux, et s&#39;abonner à un compte rassemble ses dépôts. Le mix à la une de l&#39;accueil est le plus écouté du dernier mois. </p><h2 class="mt-12 font-display text-2xl font-bold">Emporter ailleurs</h2><p class="mt-3 leading-relaxed"> Le bouton de partage d&#39;un mix ou d&#39;une playlist donne deux choses : son lien, et un lecteur à coller sur un autre site — avec son aperçu, pour voir ce que ça donnera avant de copier le code. </p><p class="mt-3 leading-relaxed"> Tout est aussi disponible en flux RSS, lisible par n&#39;importe quelle application de podcast : le site entier, un compte, une playlist, une fournée. L&#39;icône de flux apparaît à côté du titre de la page concernée. </p><h2 class="mt-12 font-display text-2xl font-bold">Le compte</h2><p class="mt-3 leading-relaxed"> Écouter ne demande rien. Un compte sert à déposer, commenter, mettre en favori, faire des playlists et s&#39;abonner. On peut le créer avec une adresse et un mot de passe, avec Google, ou avec la carte de membre du club. </p>`,22),a(`div`,f,[e(u,{to:{name:`discover`},class:`tb-btn`},{default:t(()=>[...s[0]||=[i(`Découvrir des mix`,-1)]]),_:1}),e(u,{to:{name:`upload`},class:`tb-btn-outline`},{default:t(()=>[...s[1]||=[i(`Déposer un mix`,-1)]]),_:1})])])}}});export{p as default};